mapper.select:
select  i.*,t.source costTypeSource from   financial_budget_info i left join  financial_cost_type t on  i.cost_type_id = t.id


    i.budget_id = #{budgetId}


    AND FIND_IN_SET(i.ascription_company_id,#{ascriptionCompanyId})


    AND FIND_IN_SET(i.ascription_organ_id,#{ascriptionOrganId})


    AND FIND_IN_SET(i.cost_type_id,#{costTypeId})



  limit #{pageIndex}, #{pageSize}
